function getReferencedTids(content) {
	const tids = new Set();
	const baseUrl = String(nconf.get('url') || '').replace(/\/+$/, '');
	const topicPath = /^\/topic\/(\d+)(?=\/|[?#\s)\]>"'.,;:!]|$)/;
	const withoutAbsoluteUrls = content.replace(/https?:\/\/[^\s<>"']+/gi, (url) => {
		if (baseUrl && url.startsWith(`${baseUrl}/topic/`)) {
			const match = topicPath.exec(url.slice(baseUrl.length));
			if (match && Number(match[1]) > 0) {
				tids.add(Number(match[1]));
			}
		}
		return ' ';
	});
	const relativeTopic = /(?:^|[^\w/:])\/topic\/(\d+)(?=\/|[?#\s)\]>"'.,;:!]|$)/g;
	let match = relativeTopic.exec(withoutAbsoluteUrls);
	while (match) {
		if (Number(match[1]) > 0) {
			tids.add(Number(match[1]));
		}
		match = relativeTopic.exec(withoutAbsoluteUrls);
	}
	return Array.from(tids);
}

